-- 串口协议表单整理（合并了原先的 015/016/017，内容一致，只是不再拆成三条）：
--
-- 1) 新增欧姆龙 FINS 本地串口 Omron.FINS.Serial —— 驱动与 Host Link over serial 传输层
--    早已实现并注册，但 iot_protocol 里一直缺这一条，界面上建不出这种设备。
-- 2) 移除 MC/FINS 各表单里多余的 transport 字段 —— 传输层由协议注册名固定，
--    驱动在 Connect/Ping 里用 cfg.Transport = d.transport 硬覆盖，让用户选只会误导。
-- 3) ModBus.RTU 补上缺失的串口链路参数与单帧超时（baudRate/dataBits/stopBits/parity/timeoutMs）
--    —— 解析器此前从未读取它们，永远用默认的 9600/8/1/N/5000 去连从站。
-- 4) ModBus.RTU 与 Mitsubishi.MC.Serial 的 comPort 由固定选项的 select 改为文本框
--    —— 原先只有 COM1 与 /dev/ttyUSB0 两条，而前端并未给 select 开 filterable/allow-create
--    （已核对 web/dist 产物），端口号为 COM7、/dev/ttyUSB1 的设备根本无法配置。
--
-- 用 INSERT OR REPLACE：在跑过旧 015/016 的库上重放时（清掉 schema_migrations 记录后），
-- FINS.Serial 那一行已存在，普通 INSERT 会因主键冲突让整个迁移失败。

INSERT OR REPLACE INTO "main"."iot_protocol" ("id", "name", "description", "form_json", "sort", "status", "created_at", "updated_at") VALUES ('7c2e5b41-9a3d-4f68-8b21-5d0e6a9c4f37', 'Omron.FINS.Serial', '', '{"rule":[{"type":"input","field":"comPort","title":"设备端口","info":"如 COM1、/dev/ttyUSB0","effect":{"fetch":""},"$required":true,"display":true,"hidden":false},{"type":"select","field":"baudRate","title":"波特率","info":"欧姆龙 PLC 串口出厂多为 9600","effect":{"fetch":""},"$required":false,"options":[{"label":"1200","value":"1200"},{"label":"2400","value":"2400"},{"label":"4800","value":"4800"},{"label":"9600","value":"9600"},{"label":"19200","value":"19200"},{"label":"38400","value":"38400"},{"label":"57600","value":"57600"},{"label":"115200","value":"115200"}],"display":true,"hidden":false},{"type":"select","field":"dataBits","title":"数据位","info":"","effect":{"fetch":""},"$required":false,"options":[{"label":"8","value":"8"},{"label":"7","value":"7"}],"display":true,"hidden":false},{"type":"select","field":"stopBits","title":"停止位","info":"","effect":{"fetch":""},"$required":false,"options":[{"label":"1","value":"1"},{"label":"2","value":"2"}],"display":true,"hidden":false},{"type":"select","field":"parity","title":"校验位","info":"","effect":{"fetch":""},"$required":false,"options":[{"label":"无校验","value":"N"},{"label":"偶校验","value":"E"},{"label":"奇校验","value":"O"}],"display":true,"hidden":false},{"type":"input","field":"unitNo","title":"单元号","info":"Host Link 单元号 0~31，默认 0；多台 PLC 挂同一条 485 总线时用来区分","effect":{"fetch":""},"$required":false,"display":true,"hidden":false},{"type":"select","field":"fcsMode","title":"FCS 计算窗口","info":"默认 NOSID（含 @ 但排除 SID，真机核实）；若报 FCS 校验错可改 FULL（手册标准）或 BODY","effect":{"fetch":""},"$required":false,"options":[{"label":"NOSID（含@排除SID）","value":"NOSID"},{"label":"FULL（手册标准）","value":"FULL"},{"label":"BODY（仅hex体）","value":"BODY"}],"display":true,"hidden":false},{"type":"input","field":"timeoutMs","title":"单帧超时(ms)","info":"默认 5000","effect":{"fetch":""},"$required":false,"display":true,"hidden":false},{"type":"select","field":"byteOrder","title":"字节序","info":"","effect":{"fetch":""},"$required":false,"options":[{"label":"大端","value":"BIG_ENDIAN"},{"label":"小端","value":"LITTLE_ENDIAN"}],"display":true,"hidden":false},{"type":"select","field":"wordOrder","title":"字序","info":"","effect":{"fetch":""},"$required":false,"options":[{"label":"大端","value":"BIG_ENDIAN"},{"label":"小端","value":"LITTLE_ENDIAN"}],"display":true,"hidden":false}],"options":{"form":{"inline":false,"hideRequiredAsterisk":false,"labelPosition":"right","size":"default","labelWidth":"125px"},"resetBtn":{"show":false,"innerText":"重置"},"submitBtn":{"show":false,"innerText":"提交"}}}', 1, 1, '2026-09-21 10:00:00', '2026-09-21 10:00:00');

